def apply_meta():
 for l in data:
  key=f"{l['year']}-{l['textNumber']}"
  if key not in meta:continue
  title,topic,summary,structure,evidence,tips=meta[key]
  l.update(title=title,topic=topic,summary=summary,structure=structure.split('|'),tips=[{'title':t,'body':b} for t,b in zip(['抓住文章主线','辨认论证关系','核对题目依据'],tips)])
  for q,p in zip(l['questions'],evidence):
   q['evidence']=p-1
   q['explanation']=f"参考答案为 {'ABCD'[q['answer']]}（用户提供的机构参考答案）。请回读第 {p} 段，比较选项与原文的同义改写、范围和逻辑关系。"
 (APP/'src/past-2019-2026.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))

if __name__=='__main__':apply_meta()
